{"code": "import math

def check_solution(x):
    # Standard definition of acot: range (0, pi)
    # acot(y) = math.atan(1/y) if y > 0 else math.atan(1/y) + math.pi
    if x == 0:
        return False
    y = 1/x
    if y > 0:
        acot_y = math.atan(1/y)
    else:
        acot_y = math.atan(1/y) + math.pi
    arg = math.atan(x) + acot_y
    return math.isclose(math.sin(arg), 1/3, abs_tol=1e-9)

sols = [3 + 2*math.sqrt(2), 3 - 2*math.sqrt(2), -3 + 2*math.sqrt(2), -3 - 2*math.sqrt(2)]
for s in sols:
    print(f"x = {s:.4f}, sin(...) = {math.sin(math.atan(s) + (math.atan(1/s) if 1/s > 0 else math.atan(1/s) + math.pi)):.6f}, valid: {check_solution(s)}")"}
